(
  error: unknown,
  provider: ReaderGroupingProvider
): string => {
  const providerName = provider === 'grimmory' ? 'Grimmory' : 'BookOrbit';
  const status = axios.isAxiosError(error) ? error.response?.status : undefined;
  if (status === 401 || status === 403) {
    return (
      providerName +
      ' rejected these credentials or the account cannot manage groupings. Check the username, password, and account permissions.'
    );
  }
  if (status === 404) {
    return (
      providerName +
      ' did not recognize the grouping API. Check that the service version and address are correct.'
    );
  }
  if (
    status === 413 ||
    (axios.isAxiosError(error) && error.code === 'ERR_BAD_RESPONSE')
  ) {
    return (
      providerName +
      ' returned a response that was too large to process safely.'
    );
  }
  return (
    'SeerrNG could not complete the request to ' +
    providerName +
    '. Check the service address and try again.'
  );
}

(
  provider: 'romarr' | 'questarr',
  phase:
    | 'integration handshake'
    | 'platform list'
    | 'catalog platform list'
    | 'DAT catalog platform list',
  error: unknown
): string => {
  const service = provider === 'romarr' ? 'ROMarrNG' : 'QuestarrNG';
  if (axios.isAxiosError(error)) {
    const status = error.response?.status;
    if (status === 401 || status === 403) {
      return `${service} rejected the API key (HTTP ${status}) during the ${phase}.`;
    }
    if (status === 404) {
      return `${service} returned HTTP 404 during the ${phase}. Check the service version and base path.`;
    }
    if (typeof status === 'number') {
      return `${service} returned HTTP ${status} during the ${phase}.`;
    }
    if (error.code === 'ECONNREFUSED') {
      return `${service} refused the connection during the ${phase}. Check the hostname and port.`;
    }
    if (error.code === 'ENOTFOUND') {
      return `The ${service} hostname could not be resolved during the ${phase}.`;
    }
    if (error.code === 'ETIMEDOUT' || error.code === 'ECONNABORTED') {
      return `The connection to ${service} timed out during the ${phase}. Check its address and container network.`;
    }
  }
  return `${service} connection failed during the ${phase}. Check its address and API key.`;
}

