(error: unknown): AxiosError | undefined => {
  let current = error;
  const seen = new Set<object>();

  for (
    let depth = 0;
    current !== undefined && current !== null && depth < 8;
    depth++
  ) {
    if (axios.isAxiosError(current)) {
      return current;
    }

    if (typeof current !== 'object') {
      return undefined;
    }
    if (seen.has(current)) {
      return undefined;
    }
    seen.add(current);
    current = (current as ErrorWithCause).cause;
  }

  return undefined;
}

